\c test_avocado
-- This method is used for generating symbols; examples of symbols include barcodes and QR codes.
CREATE OR REPLACE FUNCTION tests.to_base33(n bigint, min_len int default 4) RETURNs varchar AS
$BODY$
DECLARE
    alphabet text := '0123456789ABCDEFGHJKMNPQRSTUVWXYZ';
    result text := '';BEGIN
    IF n = 0 THEN
        RETURN lpad('0', min_len, '0');
    END IF;
    WHILE n > 0 LOOP
        result := substr(alphabet, ((n % 33) + 1)::int, 1) || result;
        n := n / 33;
    END LOOP;
    RETURN CASE WHEN length(result) < min_len THEN lpad(result, min_len, '0') ELSE result END;
END;
$BODY$
LANGUAGE plpgsql immutable;

CREATE OR REPLACE FUNCTION tests.next_seq(p_table_name varchar, p_yy int, p_mm int) RETURNs bigint AS
$BODY$
DECLARE
    v_counter bigint;
BEGIN
    insert into tests.shared_symbol_counter(table_name, yy, mm, counter)
    values (p_table_name, p_yy, p_mm, 1)
    on conflict (table_name, yy, mm)
    do update set counter = tests.shared_symbol_counter.counter + 1
    RETURNing counter into v_counter;
    RETURN v_counter;
END;
$BODY$
LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION tests.trg_gen_symbol_by_month() RETURNs trigger AS
$BODY$
DECLARE
    v_yy int;
    v_mm int;
    v_seq bigint;
BEGIN
    IF NULLIF(NEW.symbol, '') IS NOT null THEN
        RETURN NEW;
    END IF;
    v_yy := extract(year from now())::int % 100;
    v_mm := extract(month from now())::int;
    v_seq := tests.next_seq(TG_TABLE_NAME::varchar, v_yy, v_mm);
    NEW.symbol := lpad(v_yy::text, 2, '0') || lpad(v_mm::text, 2, '0')
            || '-' || tests.to_base33(v_seq, 4);
    RETURN NEW;
END;
$BODY$
LANGUAGE plpgsql;

-- symbol = to_base33(連番, 4)：33進数（0-9, A-Z から I/L/O を除く）、4桁ゼロ埋め。
-- 4桁で 1,185,920 件まで。超えると5桁以上に自動で伸びる（varchar(16) に収まる）。
CREATE OR REPLACE FUNCTION tests.trg_gen_symbol_seq() RETURNS TRIGGER AS
$BODY$
DECLARE
    v_seq bigint;
BEGIN
    IF NULLIF(NEW.symbol, '') IS NOT null THEN
        RETURN NEW;
    END IF;
    v_seq := tests.next_seq(TG_TABLE_NAME::varchar, 0, 0);
    NEW.symbol := tests.to_base33(v_seq, 4);
    RETURN NEW;
END;
$BODY$
LANGUAGE plpgsql;

-- This method, designed specifically for tables containing 'text_value' and 'char_count' columns, converts input text into a character count and an introductory excerpt.
CREATE OR REPLACE FUNCTION tests.trg_gen_text_summary() RETURNS TRIGGER AS
$BODY$
DECLARE
    v_lead_len INTEGER := 80;
    v_text     TEXT;
BEGIN
    IF TG_NARGS > 0 THEN
        v_lead_len := TG_ARGV[0]::INTEGER;
    END IF;
v_text := COALESCE(NEW.text_value, '');
    NEW.lead_text  := LEFT(REGEXP_REPLACE(v_text, E'[\r\n\t]+', ' ', 'g'), v_lead_len);
    -- バイト数ではなく文字数
    NEW.char_count := CHAR_LENGTH(v_text);
    RETURN NEW;
END;
$BODY$
LANGUAGE plpgsql;
COMMENT ON FUNCTION tests.trg_gen_text_summary() IS 'text_valueからlead_text(導入文)とchar_count(文字数)を算出する';

