-- info_company history trigger
CREATE OR REPLACE FUNCTION tests.trg_02_history_info_company() RETURNS trigger AS
$BODY$
DECLARE
    revisions int;
BEGIN
    IF (TG_OP = 'UPDATE') OR (TG_OP='INSERT') THEN
        SELECT Max(revision) INTO revisions FROM tests.history_info_company WHERE info_company_id=NEW.info_company_id;
        IF (revisions >= 0) THEN
            IF (
                NEW.info_company_id,
                NEW.names,
                NEW.info_address_id,
                NEW.web_page,
                NEW.ceo_names,
                NEW.symbol,
                NEW.remarks,
                NEW.remove
            ) IS NOT DISTINCT FROM (
                OLD.info_company_id,
                OLD.names,
                OLD.info_address_id,
                OLD.web_page,
                OLD.ceo_names,
                OLD.symbol,
                OLD.remarks,
                OLD.remove
            )
            THEN
                RETURN NULL;
            END IF;
            NEW.revision := revisions + 1;
        ELSE
            NEW.revision := 1;
        END IF;
        INSERT INTO tests.history_info_company (
            info_company_id,
            names,
            info_address_id,
            web_page,
            ceo_names,
            revision,
            symbol,
            remarks,
            update_at,
            update_user_id,
            update_user_history_id,
            remove
        )
        VALUES
        (
            NEW.info_company_id,
            NEW.names,
            NEW.info_address_id,
            NEW.web_page,
            NEW.ceo_names,
            NEW.revision,
            NEW.symbol,
            NEW.remarks,
            NEW.update_at,
            NEW.update_user_id,
            NEW.update_user_history_id,
            NEW.remove
        );
        RETURN NEW;
    ELSEIF (TG_OP = 'DELETE') THEN
        RETURN OLD;
    END IF;
END
$BODY$
LANGUAGE plpgsql VOLATILE;
