-- mstr_audit_std_checkitem history trigger
CREATE OR REPLACE FUNCTION tests.trg_02_history_mstr_audit_std_checkitem() RETURNS trigger AS
$BODY$
DECLARE
    revisions int;
BEGIN
    IF (TG_OP = 'UPDATE') OR (TG_OP='INSERT') THEN
        SELECT Max(revision) INTO revisions FROM tests.history_mstr_audit_std_checkitem WHERE mstr_audit_std_checkitem_id=NEW.mstr_audit_std_checkitem_id;
        IF (revisions >= 0) THEN
            IF (
                NEW.mstr_audit_std_checkitem_id,
                NEW.mstr_audit_std_id,
                NEW.code,
                NEW.control_code,
                NEW.names,
                NEW.details,
                NEW.type_class,
                NEW.formula_class,
                NEW.arg_class,
                NEW.symbol,
                NEW.remarks,
                NEW.remove
            ) IS NOT DISTINCT FROM (
                OLD.mstr_audit_std_checkitem_id,
                OLD.mstr_audit_std_id,
                OLD.code,
                OLD.control_code,
                OLD.names,
                OLD.details,
                OLD.type_class,
                OLD.formula_class,
                OLD.arg_class,
                OLD.symbol,
                OLD.remarks,
                OLD.remove
            )
            THEN
                RETURN NULL;
            END IF;
            NEW.revision := revisions + 1;
        ELSE
            NEW.revision := 1;
        END IF;
        INSERT INTO tests.history_mstr_audit_std_checkitem (
            mstr_audit_std_checkitem_id,
            mstr_audit_std_id,
            code,
            control_code,
            names,
            details,
            type_class,
            formula_class,
            arg_class,
            revision,
            symbol,
            remarks,
            update_at,
            update_user_id,
            update_user_history_id,
            remove
        )
        VALUES
        (
            NEW.mstr_audit_std_checkitem_id,
            NEW.mstr_audit_std_id,
            NEW.code,
            NEW.control_code,
            NEW.names,
            NEW.details,
            NEW.type_class,
            NEW.formula_class,
            NEW.arg_class,
            NEW.revision,
            NEW.symbol,
            NEW.remarks,
            NEW.update_at,
            NEW.update_user_id,
            NEW.update_user_history_id,
            NEW.remove
        );
        RETURN NEW;
    ELSEIF (TG_OP = 'DELETE') THEN
        RETURN OLD;
    END IF;
END
$BODY$
LANGUAGE plpgsql VOLATILE;
CREATE TRIGGER trg_02_history_mstr_audit_std_checkitem BEFORE INSERT OR UPDATE OR DELETE ON tests.mstr_audit_std_checkitem FOR EACH ROW EXECUTE
PROCEDURE tests.trg_02_history_mstr_audit_std_checkitem();


