CREATE OR REPLACE FUNCTION tests.trg_02_history_mstr_inspection() RETURNS trigger AS
$BODY$
DECLARE
    revisions int;
BEGIN
    IF (TG_OP = 'UPDATE') OR (TG_OP='INSERT') THEN
        SELECT Max(revision) INTO revisions FROM tests.history_mstr_inspection WHERE mstr_inspection_id=NEW.mstr_inspection_id;
        IF (revisions >= 0) THEN
            IF (
                NEW.mstr_inspection_id,
                NEW.code,
                NEW.names,
                NEW.inspection_kind,
                NEW.base_date,
                NEW.time_interval,
                NEW.external_inspection,
                NEW.inspection_formula_id,
                NEW.mstr_item_id,
                NEW.symbol,
                NEW.remarks,
                NEW.remove
            ) IS NOT DISTINCT FROM (
                OLD.mstr_inspection_id,
                OLD.code,
                OLD.names,
                OLD.inspection_kind,
                OLD.base_date,
                OLD.time_interval,
                OLD.external_inspection,
                OLD.inspection_formula_id,
                OLD.mstr_item_id,
                OLD.symbol,
                OLD.remarks,
                OLD.remove
            )
            THEN
                RETURN NULL;
            END IF;
            NEW.revision := revisions + 1;
        ELSE
            NEW.revision := 1;
        END IF;
        INSERT INTO tests.history_mstr_inspection (
            mstr_inspection_id,
            code,
            names,
            inspection_kind,
            base_date,
