    IF (TG_OP = 'UPDATE') OR (TG_OP='INSERT') THEN
        SELECT Max(revision) INTO revisions FROM tests.history_mstr_operation WHERE mstr_operation_id=NEW.mstr_operation_id;
        IF (revisions >= 0) THEN
            IF (
