            ) IS NOT DISTINCT FROM (
                OLD.mstr_operation_id,
                OLD.control_code,
                OLD.names,
                OLD.details,
                OLD.symbol,
                OLD.remarks,
                OLD.remove
            )
            THEN
                RETURN NULL;
            END IF;
            NEW.revision := revisions + 1;
        ELSE
            NEW.revision := 1;
        END IF;
        INSERT INTO tests.history_mstr_operation (
            mstr_operation_id,
            control_code,
            names,
            details,
            revision,
            symbol,
            remarks,
            update_at,
            update_user_id,
            update_user_history_id,
            remove
        )
        VALUES
        (
            NEW.mstr_operation_id,
            NEW.control_code,
            NEW.names,
            NEW.details,
            NEW.revision,
            NEW.symbol,
            NEW.remarks,
            NEW.update_at,
            NEW.update_user_id,
            NEW.update_user_history_id,
            NEW.remove
        );
        RETURN NEW;
    ELSEIF (TG_OP = 'DELETE') THEN
        RETURN OLD;
    END IF;
END
$BODY$
LANGUAGE plpgsql VOLATILE;
